def count_numbers_in_list(numbers_list):
    """
    Returns the number of occurrences of each number in a list.
    """
    # Define a function to count occurrences of each number
    def count_occurrence(num):
        return numbers_list.count(num)

    # Initialize a dictionary to store the counts
    counts = {}

    # Iterate over the list and count the occurrences
    for num in sorted(numbers_list):
        if num in counts:
            counts[num] += 1
        elif num < 0:
            counts[num] = 1
        else:
            counts[num] = 0

    # Return the counts as a dictionary
    return counts
