from fastapi import FastAPI
from fastapi.responses import JSONResponse
from typing import Dict
import uvicorn
import os
import boto3

app = FastAPI()

s3 = boto3.client('s3')

@app.post("/upload")
async def upload_image(file: bytes = None, file_name: str = None):
    if file is None or file_name is None:
        return JSONResponse({"error": "File is not provided"}, status_code=400)

    try:
        # Check file size
        if os.path.getsize(file_name) > 5 * 1024 * 1024:
            return JSONResponse({"error": "File size exceeds 5MB"}, status_code=400)

        # Check file extension
        if not file_name.endswith((".jpg", ".png")):
            return JSONResponse({"error": "Invalid file extension"}, status_code=400)

        # Upload file to S3
        s3.upload_fileobj(file, "your-bucket-name", file_name)

        return JSONResponse({"message": "Image uploaded successfully"}, status_code=200)

    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)
```

```python
from fastapi import FastAPI
from fastapi.responses import FileResponse
from fastapi.middleware.cors import CORSMiddleware
import os
import boto3
import io
from PIL import Image
import asyncio

app = FastAPI()

# AWS S3 client
s3 = boto3.client('s3')

# CORS middleware
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

@app.post("/upload")
async def upload_image(file: UploadFile = None):
    if file is None:
        return {"message": "No file provided"}

    try:
        # Check file size and extension
        if file.content_length > 5 * 1024 * 1024:
            return {"message": "File size exceeds 5MB limit"}
        if not file.filename.endswith((".jpg", ".png")):
            return {"message": "Invalid file extension. Only .jpg and .png allowed"}

        # Upload image to S3
        image_data = await file.read()

        # Save image to S3
        s3.upload_fileobj(image_data, "your-bucket-name", file.filename)

        # Return response
        return {"message": "Image uploaded successfully", "filename": file.filename}

    except Exception as e:
        return {"message": f"Error uploading image: {e}"}
```

