```python
from fastapi import FastAPI, File, UploadFile
from fastapi.responses import JSONResponse
import uvicorn
import boto3
import os

app = FastAPI()

s3 = boto3.client('s3')

@app.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    try:
        if file.content_type not in ["image/jpeg", "image/png"]:
            return JSONResponse(status_code=400, content={"message": "Invalid file type."})
        if file.size > 5 * 1024 * 1024:
            return JSONResponse(status_code=400, content={"message": "File size exceeds 5MB."})

        # Upload file to S3
        s3.upload_fileobj(file.file, 'your-bucket-name', file.filename)

        return JSONResponse(content={"message": "File uploaded successfully."}, status_code=200)
    except Exception as e:
        return JSONResponse(status_code=500, content={"message": str(e)})
```

