import asyncio
import websockets
from typing import List, Dict, Any, Tuple
from datetime import datetime

class WebSocketException(Exception):
    pass

class RateLimitExceeded(WebSocketException):
    pass

class MessageBuffer:
    def __init__(self, max_size: int = 20):
        self.buffer = []
        self.max_size = max_size

    def add_message(self, message: str) -> None:
        if len(self.buffer) >= self.max_size:
            self.buffer.pop(0)
        self.buffer.append(message)

    def get_last_messages(self) -> List[str]:
        return self.buffer

class WebSocketServer:
    def __init__(self, port: int = 8765):
        self.port = port
        self.clients = {}
        self.message_buffer = MessageBuffer()
        self.rate_limit_seconds = 10
        self.rate_limit_messages = 5

    async def handle_client(self, websocket: websockets.WebSocket):
        client_id = str(websocket.remote_address)
        self.clients[client_id] = websocket
        try:
            while True:
                try:
                    message = await websocket.recv()
                    if message:
                        self.message_buffer.add_message(message)
                        await self.broadcast_message(client_id, message)
                except websockets.exceptions.ConnectionClosed:
                    del self.clients[client_id]
                    break
        except WebSocketException as e:
            print(f"WebSocketException: {e}")
            await websocket.close()
            del self.clients[client_id]

    async def broadcast_message(self, sender_id: str, message: str) -> None:
        for client_id in self.clients:
            if client_id != sender_id:
                try:
                    await self.clients[client_id].send(message)
                except websockets.exceptions.ConnectionClosed:
                    del self.clients[client_id]

    async def start(self) -> None:
        async with websockets.serve(self.handle_client, "localhost", self.port):
            print(f"WebSocket server started on port {self.port}")
            await asyncio.Future()

async def main():
    server = WebSocketServer()
    await server.start()

if __name__ == "__main__":
    asyncio.run(main())
```

