import random

def guess_number_game():
    number = random.randint(1, 100)
    attempts = 0

    print("1-100 arasında bir sayı tuttum. Tahmin etmeye çalışın!")

    while True:
        try:
            guess = int(input("Tahmininiz: "))
            attempts += 1

            if guess < number:
                print("Daha yukarı!")
            elif guess > number:
                print("Daha aşağı!")
            else:
                print(f"Bravo! Doğru bildiniz. Toplam {attempts} denemede buldunuz.")
                break
        except ValueError:
            print("Lütfen bir sayı girin.")

guess_number_game()
```

```python
import random

def guess_number():
    number = random.randint(1, 100)
    attempts = 0

    while True:
        try:
            guess = int(input("Tahmin etmek istediğiniz sayıyı girin (1-100 arası): "))
            attempts += 1

            if guess < number:
                print("Daha yüksek bir sayı deneyin.")
            elif guess > number:
                print("Daha düşük bir sayı deneyin.")
            else:
                print(f"Tebrikler! {number} sayısını {attempts} denemede buldunuz.")
                break
        except ValueError:
            print("Lütfen geçerli bir sayı girin.")

if __name__ == "__main__":
    guess_number()
```

